mapper.select:
SELECT id, alarm_id, dispatch_rule_id, recipient_id, recipient_name,
recipient_phone, channel, title, content,
status, send_time, error_msg, create_time,
source_type, source_id, read_time
FROM alarm_notification

    AND alarm_id = #{alarmId}
    AND status = #{status}
    AND channel = #{channel}

ORDER BY create_time DESC

mapper.update:
UPDATE alarm_notification
SET status = #{status}, send_time = #{sendTime}, error_msg = #{errorMsg}
WHERE id = #{id}

UPDATE alarm_notification
SET read_time = NOW()
WHERE id = #{id}
  AND recipient_id = #{userId}
  AND read_time IS NULL

UPDATE alarm_notification
SET read_time = NOW()
WHERE recipient_id = #{userId}
  AND channel = #{channel}
  AND read_time IS NULL

mapper.select:
SELECT COUNT(1)
FROM alarm_notification
WHERE recipient_id = #{userId}
  AND channel = #{channel}
  AND source_type IN ('threshold', 'comprehensive', 'offline')
  AND read_time IS NULL
